import java.util.Map;

public class MessageThrottle {
    private Map<String, Integer> messageTimers;

    public MessageThrottle() {
        messageTimers = new HashMap<>();
    }

    public boolean shouldPrintMessage(int timestamp, String message) {
        if (!messageTimers.containsKey(message) || messageTimers.get(message) + 10 <= timestamp) {
            messageTimers.put(message, timestamp);
            return true;
        }
        return false;
    }
}

