    int start = i;
    int length = bb.remaining();
    while (i < start + length) {
        byte b = bb.get(i);
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (i + 1 < start + length) {
                int value = ((b & 0x1F) << 6) | (bb.get(i + 1) & 0x3F);
                sb.append((char) value);
                i += 2;
            } else {
                // Invalid sequence
                i++;
            }
        } else if ((b & 0xF0) == 0xE0) {
